/// §8.5), in declaration order. Empty when it declares none.
pub const ERROR_CODES: &[crate::DeclaredErrorCode] = &[error_codes::NOT_AUTHORIZED];
/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `webvh/sync/batch:notAuthorized`
    ///
    /// The document's proven issuer is not a configured source of this replica. The whole batch is refused.
    ///
    /// Declared `retryable: false`.
    pub const NOT_AUTHORIZED: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "webvh/sync/batch:notAuthorized",
        retryable: false,
    };
}
#[cfg(test)]
mod conformance {
    //! Round-trip tests harvested from the spec's `spec.md`,
    //! plus a `rejects_invalid_examples` test for any fixtures
    //! in `payload.invalid-examples.json` (validate feature).
    #[test]
    fn request_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:c4b2a190-7e3d-4a1f-8c2b-6d5e4f3a2b01\",\n  \"type\": \"https://trusttasks.org/spec/webvh/sync/batch/0.1\",\n  \"issuer\": \"did:webvh:QmControlScid2:control.example.com\",\n  \"recipient\": \"did:webvh:QmNodeScid3:node1.example.com\",\n  \"issuedAt\": \"2026-09-27T09:20:00Z\",\n  \"payload\": {\n    \"updates\": [\n      {\n        \"mnemonic\": \"alice\",\n        \"didId\": \"did:webvh:QmAliceScid4:did.example.com:alice\",\n        \"logContent\": \"{\\\"versionId\\\":\\\"1-QmA\\\",\\\"versionTime\\\":\\\"2026-09-01T10:00:00Z\\\"}\",\n        \"versionCount\": 1,\n        \"disabled\": false\n      },\n      {\n        \"mnemonic\": \"bob\",\n        \"didId\": \"did:webvh:QmBobScid5:did.example.com:bob\",\n        \"logContent\": \"{\\\"versionId\\\":\\\"1-QmC\\\",\\\"versionTime\\\":\\\"2026-09-02T10:00:00Z\\\"}\",\n        \"versionCount\": 1,\n        \"disabled\": true\n      }\n    ]\n  }\n}\n";
        let doc: crate::TrustTask<super::Payload> =
            serde_json::from_str(JSON).expect("deserialize request example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "request example failed round-trip");
    }
    #[test]
    fn response_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:c4b2a190-7e3d-4a1f-8c2b-6d5e4f3a2b02\",\n  \"type\": \"https://trusttasks.org/spec/webvh/sync/batch/0.1#response\",\n  \"threadId\": \"urn:uuid:c4b2a190-7e3d-4a1f-8c2b-6d5e4f3a2b01\",\n  \"issuer\": \"did:webvh:QmNodeScid3:node1.example.com\",\n  \"recipient\": \"did:webvh:QmControlScid2:control.example.com\",\n  \"issuedAt\": \"2026-09-27T09:20:02Z\",\n  \"payload\": {\n    \"results\": [\n      { \"mnemonic\": \"alice\", \"status\": \"unchanged\" },\n      { \"mnemonic\": \"bob\", \"status\": \"refused\", \"code\": \"webvh/sync/update:historyRewrite\" }\n    ]\n  }\n}\n";
        let doc: crate::TrustTask<super::Response> =
            serde_json::from_str(JSON).expect("deserialize response example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "response example failed round-trip");
    }
    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            ("Missing updates.", "{}"),
            (
                "Empty updates — a batch carries at least one entry.",
                "{\n  \"updates\": []\n}",
            ),
            (
                "Entry missing disabled.",
                "{\n  \"updates\": [\n    {\n      \"didId\": \"did:webvh:QmA:did.example.com:alice\",\n      \"logContent\": \"{}\",\n      \"mnemonic\": \"alice\",\n      \"versionCount\": 1\n    }\n  ]\n}",
            ),
            (
                "Entry uses 0.1's snake_case members.",
                "{\n  \"updates\": [\n    {\n      \"did_id\": \"did:webvh:QmA:did.example.com:alice\",\n      \"disabled\": false,\n      \"log_content\": \"{}\",\n      \"mnemonic\": \"alice\",\n      \"version_count\": 1\n    }\n  ]\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
}
